## 8. SDKs and Libraries

Official SDKs for TypeScript and Python are under active development. In the meantime, you interact directly with the REST API.

Here is a complete, reusable JavaScript helper class that wraps authentication, manages quote-and-swap workflows, and handles errors:

```javascript
class TowerClient {
  constructor(apiKey, baseUrl = "https://www.tower.exchange/api/public") {
    this.apiKey = apiKey;
    this.baseUrl = baseUrl;
  }

  async request(endpoint, options = {}) {
    const url = this.baseUrl + endpoint;
    const requestHeaders = Object.assign(
      {
        "Authorization": "Bearer " + this.apiKey,
        "Content-Type": "application/json"
      },
      options.headers || {}
    );

    const fetchConfig = Object.assign({}, options, { headers: requestHeaders });
    const response = await fetch(url, fetchConfig);
    const data = await response.json();

    if (!response.ok || data.success === false) {
      const errorMessage = data.error || "HTTP error " + response.status;
      throw new Error("Tower API Error [" + response.status + "]: " + errorMessage);
    }

    return data;
  }

  async getTokens() {
    return this.request("/tokens", { method: "GET" });
  }

  async getChains() {
    return this.request("/chains", { method: "GET" });
  }

  async getPrices() {
    return this.request("/prices", { method: "GET" });
  }

  async getWalletBalance(address, chainId, rpcUrl, tokenAddress, balanceType = "token") {
    return this.request("/wallet/balance", {
      method: "POST",
      body: JSON.stringify({ address, chainId, rpcUrl, tokenAddress, balanceType })
    });
  }

  async getSwapQuote(inputToken, outputToken, inputAmount, slippageTolerance = 50) {
    return this.request("/swap/quote", {
      method: "POST",
      body: JSON.stringify({ inputToken, outputToken, inputAmount, slippageTolerance })
    });
  }

  async buildSwapTransaction(quote, userAddress) {
    return this.request("/swap/build-tx", {
      method: "POST",
      body: JSON.stringify({ quote, userAddress })
    });
  }

  async swap(inputToken, outputToken, inputAmount, userAddress, slippageTolerance = 50) {
    const quoteResponse = await this.getSwapQuote(inputToken, outputToken, inputAmount, slippageTolerance);
    const quote = quoteResponse.data;
    const txResponse = await this.buildSwapTransaction(quote, userAddress);
    return {
      quote: quote,
      transactions: txResponse.data
    };
  }
}

// Example usage:
async function main() {
  const tower = new TowerClient("sk_live_9f83a2d1e0c4b5a67890123456789abcdef0");
  const result = await tower.swap("USDC", "EURC", "100000000", "0xa54FFd258815Ee711bA0d3Dbb7fA786AEA6095Fb", 50);
  console.log("Optimal Route:", result.quote.dexName);
  console.log("Swap Calldata:", result.transactions.swap.data);
}

main().catch(console.error);
```

